int func(vector<int>& nums) {
    function<int(int, int)> divideAndConquer = [&](int left, int right) -> int {
        if (left == right) return nums[left];
        int mid = (left + right) / 2;
        int leftMax = divideAndConquer(left, mid);
        int rightMax = divideAndConquer(mid + 1, right);
        int leftSum = 0, rightSum = 0, currentSum = 0;
        for (int i = mid; i >= left; i--) {
            currentSum += nums[i];
            leftSum = max(leftSum, currentSum);
        }
        currentSum = 0;
        for (int i = mid + 1; i <= right; i++) {
            currentSum += nums[i];
            rightSum = max(rightSum, currentSum);
        }
        return max({leftMax, rightMax, leftSum + rightSum});
    };
    return divideAndConquer(0, nums.size() - 1);
}

